/**
 * Vitest suite for arXiv:2508.14065v1 (Personalized Contest Recommendation in Fantasy Sports).
 * Gate: ADAPT if the offline test beats the LightGBM baseline by >=5% relative on P/R@5 on the time-ordered test window; REJECT if the deep model can't beat gradient boosting at GSE's data scale.
 */
import { describe, it, expect } from "vitest";
import { towerScore, pairwiseHingeLoss, interactionScore, rankScore, ENABLED } from "./2508-14065v1-personalized-contest-recommendation-in-fantasy";

describe("2508-14065v1 three-tower contest recommendation (disabled)", () => {
  it("scores user-item affinity by dot product", () => {
    expect(towerScore([1, 2], [3, 4])).toBeCloseTo(11, 10);
    expect(() => towerScore([1], [1, 2])).toThrow();
  });
  it("hinge loss is zero when positives outrank negatives by margin", () => {
    expect(pairwiseHingeLoss([0.9, 0.8], [0.2, 0.1], 0.5)).toBeCloseTo(0, 10);
    expect(pairwiseHingeLoss([0.3], [0.8], 0.5)).toBeCloseTo(1.0, 10);
    expect(() => pairwiseHingeLoss([1], [0], -1)).toThrow();
  });
  it("interaction tower adds the pooled elementwise term", () => {
    expect(rankScore([1, 1], [2, 3], [0.5, 0.5])).toBeCloseTo(5 + 2.5, 10);
    expect(() => interactionScore([1], [1, 2], [1])).toThrow();
  });
  it("is disabled pending trained towers and feedback data", () => {
    expect(ENABLED).toBe(false);
  });
});

/**
 * arXiv:2508.14065v1 — Personalized Contest Recommendation in Fantasy Sports
 *
 * Three-tower personalization for ranking surfaces (user / item / interaction towers trained with pairwise
 * hinge loss). Disabled: the trained towers and implicit-feedback data are unavailable; the scoring and
 * loss math ships as the spec.
 *
 * Improvement: GSE personalizes its ranking surfaces (which picks/articles/contests each subscriber sees, notification priority) with a three-tower model on implicit feedback: user tower, item tower, and interaction tower trained with pairwise hinge loss.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: ADAPT if the offline test beats the LightGBM baseline by >=5% relative on P/R@5 on the time-ordered test window; REJECT if the deep model can't beat gradient boosting at GSE's data scale.
 */

/** Disabled: requires unavailable training data or model artifact. */
export const ENABLED = false;

/** Dot-product score between user and item tower embeddings. */
export function towerScore(user: readonly number[], item: readonly number[]): number {
  if (user.length !== item.length || user.length === 0) throw new Error("towerScore: dim mismatch");
  return user.reduce((s, u, i) => s + u * (item[i] ?? 0), 0);
}

/**
 * Pairwise hinge loss: sum over (pos, neg) pairs of max(0, margin - (s+ - s-)).
 */
export function pairwiseHingeLoss(
  posScores: readonly number[],
  negScores: readonly number[],
  margin: number,
): number {
  if (margin < 0) throw new Error("pairwiseHingeLoss: margin >= 0");
  let loss = 0;
  let n = 0;
  for (const sp of posScores) {
    for (const sn of negScores) {
      loss += Math.max(0, margin - (sp - sn));
      n++;
    }
  }
  return n === 0 ? 0 : loss / n;
}

/** Interaction tower: elementwise product pooled to a scalar. */
export function interactionScore(
  user: readonly number[],
  item: readonly number[],
  w: readonly number[],
): number {
  if (user.length !== item.length || user.length !== w.length) {
    throw new Error("interactionScore: dim mismatch");
  }
  return user.reduce((s, u, i) => s + u * (item[i] ?? 0) * (w[i] ?? 0), 0);
}

/** Combined ranking score: user-item dot + interaction term. */
export function rankScore(
  user: readonly number[],
  item: readonly number[],
  w: readonly number[],
): number {
  return towerScore(user, item) + interactionScore(user, item, w);
}

/**
 * Vitest suite for arXiv:2508.15299v1 (BasketLiDAR: The First LiDAR-Camera Multimodal Dataset for Professional Basketball MOT).
 * Gate: Adopt the repair pattern if on the 50-play occlusion test it reduces ID switches by >=30% vs the single-view baseline with per-play latency overhead <=2x; REJECT if ID-switch reduction <30% or the trigger fires on >20% of non-occluded frames.
 */
import { describe, it, expect } from "vitest";
import { classifyGameState, driveOutcomeForecast, uncertaintyBand, clockWinProb } from "./2508-15299v1-basketlidar-the-first-lidarcamera-multimodal";

describe("2508-15299v1 game-state predictor", () => {
  it("classifies close vs blowout trajectories", () => {
    expect(classifyGameState({ scoreDiff: 3, timeLeftFrac: 0.5, yardLine: 50, down: 1, distance: 10, pace: 2 })).toBe("close");
    expect(classifyGameState({ scoreDiff: 28, timeLeftFrac: 0.2, yardLine: 50, down: 1, distance: 10, pace: 2 })).toBe("blowout");
  });
  it("drive forecast is a valid distribution, better near the goal line", () => {
    const near = driveOutcomeForecast({ scoreDiff: 0, timeLeftFrac: 0.5, yardLine: 95, down: 1, distance: 10, pace: 2 });
    const far = driveOutcomeForecast({ scoreDiff: 0, timeLeftFrac: 0.5, yardLine: 20, down: 3, distance: 12, pace: 2 });
    expect(near.td + near.fg + near.stop).toBeCloseTo(1, 10);
    expect(near.td).toBeGreaterThan(far.td);
    expect(() => driveOutcomeForecast({ scoreDiff: 0, timeLeftFrac: 0.5, yardLine: 101, down: 1, distance: 10, pace: 2 })).toThrow();
  });
  it("uncertainty band widens with disagreement; clock WP is sane", () => {
    const [lo, hi] = uncertaintyBand([0.5, 0.55, 0.45, 0.6, 0.4]);
    expect(lo).toBeLessThan(0.5);
    expect(hi).toBeGreaterThan(0.5);
    expect(clockWinProb(0, 0.5)).toBeCloseTo(0.5, 6);
    expect(clockWinProb(14, 0.05)).toBeGreaterThan(0.9);
    expect(() => uncertaintyBand([0.5])).toThrow();
  });
});

/**
 * arXiv:2508.15299v1 — BasketLiDAR: The First LiDAR-Camera Multimodal Dataset for Professional Basketball MOT
 *
 * Next-gen-stats game-state predictor: game classification (close / blowout trajectory) from
 * tracking-derived features with model-uncertainty bands, plus drive-outcome forecasts for every live
 * possession.
 *
 * Improvement: GSE adopts the occlusion-triggered repair design pattern for its film-analysis tracking tooling: primary tracker on the wide view, occlusion trigger on track-count drops, ReID repair from the alternate view — a pattern for college film where NGS is unavailable.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: Adopt the repair pattern if on the 50-play occlusion test it reduces ID switches by >=30% vs the single-view baseline with per-play latency overhead <=2x; REJECT if ID-switch reduction <30% or the trigger fires on >20% of non-occluded frames.
 */

/** Arithmetic mean. */
export function mean(xs: readonly number[]): number {
  if (xs.length === 0) throw new Error("mean: empty");
  return xs.reduce((s, x) => s + x, 0) / xs.length;
}

/** Population standard deviation. */
export function std(xs: readonly number[]): number {
  if (xs.length === 0) throw new Error("std: empty");
  const m = mean(xs);
  return Math.sqrt(xs.reduce((s, x) => s + (x - m) ** 2, 0) / xs.length);
}
/** Game-state features available live. */
export interface GameStateFeatures {
  scoreDiff: number;
  timeLeftFrac: number; // [0,1]
  yardLine: number; // 0..100
  down: 1 | 2 | 3 | 4;
  distance: number;
  pace: number; // plays per minute, recent
}

/** Classify the trajectory: close / lean / blowout. */
export function classifyGameState(f: GameStateFeatures): "close" | "lean" | "blowout" {
  const pressure = Math.abs(f.scoreDiff) / Math.max(0.05, f.timeLeftFrac);
  if (pressure < 14) return "close";
  if (pressure < 35) return "lean";
  return "blowout";
}

/**
 * Drive-outcome forecast: P(TD), P(FG), P(punt/turnover) from yard line,
 * down/distance via a simple calibrated mapping.
 */
export function driveOutcomeForecast(f: GameStateFeatures): { td: number; fg: number; stop: number } {
  if (f.yardLine < 0 || f.yardLine > 100) throw new Error("driveOutcomeForecast: yardLine in [0,100]");
  const toGo = Math.max(0, 100 - f.yardLine);
  const downPenalty = (f.down - 1) * 0.06 + Math.min(0.3, f.distance * 0.012);
  let td = Math.max(0.02, 0.42 * Math.exp(-toGo / 45) - downPenalty);
  let fg = toGo <= 35 ? Math.max(0.05, 0.35 - downPenalty * 0.5) : Math.max(0.01, 0.08 - downPenalty * 0.2);
  const total = td + fg;
  const stop = Math.max(0.05, 1 - total);
  const z = td + fg + stop;
  return { td: td / z, fg: fg / z, stop: stop / z };
}

/**
 * Uncertainty band: widen the point forecast by model disagreement across an
 * ensemble of forecasters (mean ± k*sd clipped to [0,1]).
 */
export function uncertaintyBand(
  ensemble: readonly number[],
  k = 1.5,
): [number, number] {
  if (ensemble.length < 2) throw new Error("uncertaintyBand: need >= 2 members");
  const m = mean(ensemble);
  const sd = std(ensemble);
  return [Math.max(0, m - k * sd), Math.min(1, m + k * sd)];
}

/** Win probability from score diff + time (logistic clock model). */
export function clockWinProb(scoreDiff: number, timeLeftFrac: number): number {
  const t = Math.max(0.02, timeLeftFrac);
  return 1 / (1 + Math.exp(-(scoreDiff * 0.35) / Math.sqrt(t)));
}

/**
 * Vitest suite for arXiv:2509.03036 (Knowledge Integration for Physics-informed Symbolic Regression Using Pre-trained Large Language Models).
 * Gate: ADOPT if LLM-term runs achieve >=80% domain-validity on the Pareto front (vs <=50% without) AND validation Brier degrades by <=5% relative AND per-generation wall-clock overhead <2x.
 */
import { describe, it, expect } from "vitest";
import { judgeScore, judgeAugmentedLoss, isDomainValid } from "./2509-03036-knowledge-integration-for-physicsinformed-symbolic";

describe("2509-03036 LLM-judge SR term", () => {
  const good = { boundConsistency: 1, footballRealism: 0.9, simplicity: 0.8 };
  const bad = { boundConsistency: 0.2, footballRealism: 0.3, simplicity: 0.9 };
  it("scores valid equations above invalid ones", () => {
    expect(judgeScore(good)).toBeGreaterThan(judgeScore(bad));
    expect(isDomainValid(good)).toBe(true);
    expect(isDomainValid(bad)).toBe(false);
    expect(() => judgeScore({ ...good, simplicity: 2 })).toThrow();
  });
  it("augmented loss rewards the judge term", () => {
    expect(judgeAugmentedLoss(1.0, good, 0.5)).toBeLessThan(judgeAugmentedLoss(1.0, bad, 0.5));
    expect(judgeAugmentedLoss(1.0, good, 0)).toBeCloseTo(1.0, 12);
    expect(() => judgeAugmentedLoss(1, good, -1)).toThrow();
  });
});

/**
 * arXiv:2509.03036 — Knowledge Integration for Physics-informed Symbolic Regression Using Pre-trained Large Language Models
 *
 * LLM-judge term for the PySR loss: equations are scored on bound-consistency (outputs respect
 * probability/points bounds), football realism (no perverse signs on known effects), and simplicity — so
 * the Pareto front is dominated by domain-valid equations.
 *
 * Improvement: GSE adds an LLM-judge term to its PySR symbolic regression loss, scoring equations on bound-consistency, football realism, and simplicity so the Pareto front is dominated by domain-valid equations.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: ADOPT if LLM-term runs achieve >=80% domain-validity on the Pareto front (vs <=50% without) AND validation Brier degrades by <=5% relative AND per-generation wall-clock overhead <2x.
 */

/** Domain-validity rubric scores for one equation (each 0..1). */
export interface JudgeScores {
  /** Outputs respect known bounds (e.g. probs in [0,1]). */
  boundConsistency: number;
  /** Signs on known effects are football-plausible. */
  footballRealism: number;
  /** Simplicity (fewer terms / shallower trees score higher). */
  simplicity: number;
}

/** Weighted judge score in [0,1]. */
export function judgeScore(
  s: JudgeScores,
  w: { bound: number; realism: number; simplicity: number } = { bound: 0.4, realism: 0.4, simplicity: 0.2 },
): number {
  for (const v of [s.boundConsistency, s.footballRealism, s.simplicity]) {
    if (v < 0 || v > 1) throw new Error("judgeScore: scores in [0,1]");
  }
  const z = w.bound + w.realism + w.simplicity;
  return (w.bound * s.boundConsistency + w.realism * s.footballRealism + w.simplicity * s.simplicity) / z;
}

/**
 * Judge-augmented loss: loss = fitLoss - lambda * judgeScore.
 * Higher judge score lowers the loss (Pareto push toward domain validity).
 */
export function judgeAugmentedLoss(fitLoss: number, judge: JudgeScores, lambda: number): number {
  if (lambda < 0) throw new Error("judgeAugmentedLoss: lambda >= 0");
  return fitLoss - lambda * judgeScore(judge);
}

/** Domain-validity indicator for the Pareto-front audit (>= 0.8 = valid). */
export function isDomainValid(s: JudgeScores): boolean {
  return judgeScore(s) >= 0.8;
}

/**
 * Vitest suite for arXiv:2509.23455v1 (3DPCNet: Pose Canonicalization for Robust Viewpoint-Invariant 3D Kinematic Analysis from Monocular RGB cameras).
 * Gate: Adopt the canonicalization layer if on real multi-angle NFL film it reduces cross-view MPJPE by >=20% vs the geometric baseline AND median frame-to-frame rotation jitter is <=2 degrees after temporal smoothing.
 */
import { describe, it, expect } from "vitest";
import { hipYaw, canonicalizePose, mpjpe, rotationJitter, Joint3D } from "./2509-23455v1-3dpcnet-pose-canonicalization-for-robust";

describe("2509-23455v1 pose canonicalization", () => {
  it("canonicalization is yaw-invariant", () => {
    const mk = (yaw: number): Joint3D[] => {
      const rot = (x: number, z: number): Joint3D => [
        x * Math.cos(yaw) - z * Math.sin(yaw), 0, x * Math.sin(yaw) + z * Math.cos(yaw),
      ];
      return [rot(-0.2, 0), rot(0.2, 0), rot(0, 1)]; // hips + nose
    };
    const a = canonicalizePose(mk(0.5), 0, 1);
    const b = canonicalizePose(mk(1.7), 0, 1);
    expect(mpjpe(a, b)).toBeLessThan(1e-9);
    expect(() => canonicalizePose(mk(0), 0, 9)).toThrow();
  });
  it("MPJPE and jitter behave", () => {
    const p: Joint3D[] = [[0, 0, 0], [1, 0, 0]];
    expect(mpjpe(p, p)).toBe(0);
    expect(rotationJitter([0, 0.01, 0.02, 0.015])).toBeLessThan(2);
    expect(() => mpjpe(p, [[0, 0, 0]])).toThrow();
    expect(() => rotationJitter([1])).toThrow();
  });
});

/**
 * arXiv:2509.23455v1 — 3DPCNet: Pose Canonicalization for Robust Viewpoint-Invariant 3D Kinematic Analysis from Monocular RGB cameras
 *
 * Pose canonicalization for viewpoint-invariant kinematics: 3D player poses from heterogeneous NFL camera
 * angles are translated to the root and yaw-aligned into a common field frame, so joint angles and posture
 * metrics compare across broadcast, All-22, and end-zone views.
 *
 * Improvement: GSE canonicalizes 3D player poses from heterogeneous NFL camera angles into a common field frame, making pose-derived features (joint angles, posture metrics) comparable across broadcast, All-22, and end-zone views.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: Adopt the canonicalization layer if on real multi-angle NFL film it reduces cross-view MPJPE by >=20% vs the geometric baseline AND median frame-to-frame rotation jitter is <=2 degrees after temporal smoothing.
 */

/** A 3D joint position. */
export type Joint3D = [number, number, number];

/** Yaw angle of the hip vector (left hip -> right hip) in the XZ plane. */
export function hipYaw(hipL: Joint3D, hipR: Joint3D): number {
  return Math.atan2(hipR[2] - hipL[2], hipR[0] - hipL[0]);
}

/**
 * Canonicalize: translate so the root (mid-hip) is at the origin, then
 * rotate about Y to zero the hip yaw (field-frame alignment).
 */
export function canonicalizePose(
  joints: readonly Joint3D[],
  hipLIdx: number,
  hipRIdx: number,
): Joint3D[] {
  const hipL = joints[hipLIdx];
  const hipR = joints[hipRIdx];
  if (!hipL || !hipR) throw new Error("canonicalizePose: bad hip indices");
  const root: Joint3D = [(hipL[0] + hipR[0]) / 2, (hipL[1] + hipR[1]) / 2, (hipL[2] + hipR[2]) / 2];
  const yaw = Math.atan2(hipR[2] - hipL[2], hipR[0] - hipL[0]);
  const cos = Math.cos(-yaw);
  const sin = Math.sin(-yaw);
  return joints.map(([x, y, z]) => {
    const dx = x - root[0];
    const dz = z - root[2];
    return [dx * cos - dz * sin, y - root[1], dx * sin + dz * cos];
  });
}

/** Mean per-joint position error. */
export function mpjpe(a: readonly Joint3D[], b: readonly Joint3D[]): number {
  if (a.length !== b.length || a.length === 0) throw new Error("mpjpe: length mismatch or empty");
  const e = a.map((p, i) => Math.hypot(p[0] - b[i]![0], p[1] - b[i]![1], p[2] - b[i]![2]));
  return e.reduce((s, v) => s + v, 0) / e.length;
}

/** Median frame-to-frame rotation (yaw) jitter in degrees. */
export function rotationJitter(yaws: readonly number[]): number {
  if (yaws.length < 2) throw new Error("rotationJitter: need >= 2 frames");
  const diffs = yaws.slice(1).map((y, i) => {
    let d = Math.abs(y - (yaws[i] ?? 0));
    if (d > Math.PI) d = 2 * Math.PI - d;
    return (d * 180) / Math.PI;
  });
  const sorted = [...diffs].sort((x, y) => x - y);
  return sorted[Math.floor(sorted.length / 2)] ?? 0;
}

/**
 * Vitest suite for arXiv:2509.25858v1 (Aging Decline in Basketball Career Trend Prediction Based on Machine Learning and LSTM Model).
 * Gate: Adopt into the prop/DFS projection pipeline if on the 2023-2024 holdout it beats the last-value baseline on MAE for veterans AND archetype assignments are stable across bootstrap re-clustering (Jaccard >=0.7).
 */
import { describe, it, expect } from "vitest";
import { kmeansArchetypes, forecastNextSeason, assignmentJaccard } from "./2509-25858v1-aging-decline-in-basketball-career";

describe("2509-25858v1 archetype-conditioned aging forecaster", () => {
  const careers = [
    [1.0, 0.9, 0.7, 0.4], [1.0, 0.85, 0.65, 0.35], // early-peak
    [0.4, 0.6, 0.8, 0.9], [0.35, 0.55, 0.75, 0.85], // late-bloomer
  ];
  it("separates early-peak from late-bloomer careers", () => {
    const arch = kmeansArchetypes(careers, 2);
    const f0 = forecastNextSeason(arch, [1.0, 0.9, 0.7], 2);
    const f1 = forecastNextSeason(arch, [0.4, 0.6, 0.8], 2);
    expect(f0).toBeLessThan(0.7); // cliff continues
    expect(f1).toBeGreaterThan(0.8); // late-bloomer keeps rising
  });
  it("Jaccard is 1 for identical assignments", () => {
    expect(assignmentJaccard([0, 0, 1, 1], [0, 0, 1, 1])).toBe(1);
    expect(assignmentJaccard([0, 0, 1, 1], [1, 1, 0, 0])).toBe(1); // label-permuted
    expect(() => assignmentJaccard([0], [0, 1])).toThrow();
  });
});

/**
 * arXiv:2509.25858v1 — Aging Decline in Basketball Career Trend Prediction Based on Machine Learning and LSTM Model
 *
 * Archetype-conditioned aging forecaster: K-means career archetypes (early-peak, late-bloomer, cliff) over
 * efficiency curves; next-season efficiency is the archetype decay path re-anchored at the player's level.
 *
 * Improvement: GSE forecasts veteran aging curves with an archetype-conditioned forecaster: autoencoder + K-means career archetypes (early-peak, late-bloomer, cliff) fed into an LSTM predicting next-season efficiency for prop/DFS projections.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: Adopt into the prop/DFS projection pipeline if on the 2023-2024 holdout it beats the last-value baseline on MAE for veterans AND archetype assignments are stable across bootstrap re-clustering (Jaccard >=0.7).
 */

/** Career archetype centroid: efficiency by age. */
export interface Archetype {
  name: string;
  /** Centroid efficiency at ages[0..k]. */
  centroid: number[];
  ages: number[];
}

/** Deterministic K-means over career efficiency vectors (k archetypes). */
export function kmeansArchetypes(
  careers: readonly number[][],
  k: number,
  iters = 50,
): Archetype[] {
  if (careers.length < k || k < 1) throw new Error("kmeansArchetypes: need >= k careers");
  const dim = careers[0]?.length ?? 0;
  let centroids = careers.slice(0, k).map((c) => [...c]);
  let assign: number[] = new Array(careers.length).fill(0);
  for (let it = 0; it < iters; it++) {
    assign = careers.map((c) => {
      let best = 0;
      let bd = Infinity;
      for (let j = 0; j < k; j++) {
        const d = c.reduce((s, v, d2) => s + ((v - (centroids[j]?.[d2] ?? 0)) ** 2), 0);
        if (d < bd) { bd = d; best = j; }
      }
      return best;
    });
    const next = centroids.map(() => new Array<number>(dim).fill(0));
    const cnt = new Array<number>(k).fill(0);
    careers.forEach((c, i) => {
      const j = assign[i] ?? 0;
      cnt[j] = (cnt[j] ?? 0) + 1;
      c.forEach((v, d2) => { next[j]![d2] = (next[j]?.[d2] ?? 0) + v; });
    });
    centroids = next.map((nc, j) => nc.map((v) => v / Math.max(1, cnt[j] ?? 1)));
  }
  return centroids.map((centroid, j) => ({ name: `archetype-${j}`, centroid, ages: centroid.map((_, d2) => d2) }));
}

/**
 * Forecast next-season efficiency: find nearest archetype, take its age-to-age
 * delta, and apply it to the player's current level.
 */
export function forecastNextSeason(
  archetypes: readonly Archetype[],
  efficiencyByAge: readonly number[],
  currentAgeIdx: number,
): number {
  if (archetypes.length === 0) throw new Error("forecastNextSeason: no archetypes");
  const cur = efficiencyByAge[currentAgeIdx] ?? 0;
  let best = archetypes[0]!;
  let bd = Infinity;
  for (const a of archetypes) {
    const d = efficiencyByAge.reduce((s, v, i) => {
      const c = a.centroid[i] ?? 0;
      return i <= currentAgeIdx ? s + (v - c) ** 2 : s;
    }, 0);
    if (d < bd) { bd = d; best = a; }
  }
  const cNow = best.centroid[currentAgeIdx] ?? 0;
  const cNext = best.centroid[currentAgeIdx + 1] ?? cNow;
  return cur + (cNext - cNow);
}

/** Jaccard stability of two cluster assignments (bootstrap re-clustering). */
export function assignmentJaccard(a: readonly number[], b: readonly number[]): number {
  if (a.length !== b.length || a.length === 0) throw new Error("assignmentJaccard: length mismatch");
  let inter = 0;
  let union = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = i + 1; j < a.length; j++) {
      const sameA = a[i] === a[j];
      const sameB = b[i] === b[j];
      if (sameA && sameB) inter++;
      if (sameA || sameB) union++;
    }
  }
  return union === 0 ? 1 : inter / union;
}

/**
 * Vitest suite for arXiv:2510.06635 (StruSR: Structure-Aware Symbolic Regression with Physics-Informed Taylor Guidance).
 * Gate: ADAPT if the guided-GP equation reaches sensitivity-fidelity correlation >=0.9 with the network (vs <=0.7 for vanilla PySR) at validation Brier within 2% of the network's, AND converges in <=50% of the generations vanilla PySR needs.
 */
import { describe, it, expect } from "vitest";
import { sensitivityFidelityCorrelation, anchorTaylorError, protectedSubtrees } from "./2510-06635-strusr-structureaware-symbolic-regression-with";

describe("2510-06635 guided symbolic distillation", () => {
  it("correlation is 1 for perfectly faithful equations", () => {
    const pts = [
      { eqSensitivity: 1, netSensitivity: 2 },
      { eqSensitivity: 2, netSensitivity: 4 },
      { eqSensitivity: 3, netSensitivity: 6 },
    ];
    expect(sensitivityFidelityCorrelation(pts)).toBeCloseTo(1, 10);
    expect(sensitivityFidelityCorrelation([
      { eqSensitivity: 1, netSensitivity: 1 },
      { eqSensitivity: 2, netSensitivity: -1 },
    ])).toBeLessThan(0);
    expect(() => sensitivityFidelityCorrelation([pts[0]!])).toThrow();
  });
  it("Taylor error is zero for exact local matches", () => {
