/**
 * arXiv:2604.17065v1 — BasketHAR: A Multimodal Dataset for Human Activity Recognition and Sport Analysis in Basketball Training Scenarios
 *
 * LoRA-ImageBind IMU/text alignment recipe for football action classification: cosine-similarity
 * cross-modal alignment with an InfoNCE loss, leave-one-chunk-out evaluation, macro-F1 reporting. Disabled:
 * pretrained encoders and the training run are unavailable.
 *
 * Improvement: Port the LoRA-ImageBind IMU/text alignment recipe to NFL practice-wearable or NGS-derived motion features for football action classification (route stem, break, catch, block engagement, tackle), feeding weekly practice-load report editorial products.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: ADAPT the alignment method if a reimplementation on the public BasketHAR data reaches macro F1 ≥ 0.65 within a clean leave-one-chunk-out protocol; reject the method if macro F1 falls below 0.55 once window leakage is removed.
 */

/** Disabled: requires unavailable training data or model artifact. */
export const ENABLED = false;

/** Cosine similarity between modality embeddings. */
export function cosSim(a: readonly number[], b: readonly number[]): number {
  if (a.length !== b.length || a.length === 0) throw new Error("cosSim: dim mismatch");
  const dot = a.reduce((s, v, i) => s + v * (b[i] ?? 0), 0);
  const na = Math.hypot(...a);
  const nb = Math.hypot(...b);
  return na === 0 || nb === 0 ? 0 : dot / (na * nb);
}

/**
 * InfoNCE alignment loss for one anchor: -log(exp(s+/tau) / sum_j exp(s_j/tau)).
 */
export function infoNCELoss(sims: readonly number[], posIdx: number, tau: number): number {
  if (tau <= 0) throw new Error("infoNCELoss: tau > 0");
  if (posIdx < 0 || posIdx >= sims.length) throw new Error("infoNCELoss: bad posIdx");
  const mx = Math.max(...sims);
  const ex = sims.map((s) => Math.exp((s - mx) / tau));
  const z = ex.reduce((s, e) => s + e, 0);
  return -Math.log(Math.max(1e-12, (ex[posIdx] ?? 0) / z));
}

/** Leave-one-chunk-out fold assignment (chunk = contiguous block). */
export function leaveOneChunkOut(n: number, nChunks: number): number[] {
  if (nChunks < 2) throw new Error("leaveOneChunkOut: nChunks >= 2");
  if (n <= 0) throw new Error("leaveOneChunkOut: n > 0");
  return Array.from({ length: n }, (_, i) => Math.min(nChunks - 1, Math.floor((i * nChunks) / n)));
}

/** Macro F1 over classes. */
export function macroF1(
  pred: readonly string[],
  truth: readonly string[],
): number {
  if (pred.length !== truth.length || pred.length === 0) {
    throw new Error("macroF1: length mismatch or empty");
  }
  const classes = [...new Set(truth)];
  const f1s = classes.map((c) => {
    let tp = 0, fp = 0, fn = 0;
    pred.forEach((p, i) => {
      if (p === c && truth[i] === c) tp++;
      else if (p === c) fp++;
      else if (truth[i] === c) fn++;
    });
    const prec = tp + fp === 0 ? 0 : tp / (tp + fp);
    const rec = tp + fn === 0 ? 0 : tp / (tp + fn);
    return prec + rec === 0 ? 0 : (2 * prec * rec) / (prec + rec);
  });
  return f1s.reduce((s, f) => s + f, 0) / f1s.length;
}

/**
 * Vitest suite for arXiv:2604.24366v2 (The Anatomy of a Decentralized Prediction Market: Microstructure Evidence from the Polymarket Order Book).
 * Gate: Adopt the sports-only replication and the spread-premium signal-weighting if direction-agreement and stylized facts replicate within sampling noise.
 */
import { describe, it, expect } from "vitest";
import { rffMap, drawRffParams, updateMeanEmbedding, mmdWitness } from "./2604-24366v2-the-anatomy-of-a-decentralized";

function lcg(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  };
}
describe("2604-24366v2 online covariate-shift detection", () => {
  it("detects drift between train and live feature streams", () => {
    const rng = lcg(77);
    const { W, b } = drawRffParams(2, 32, rng);
    let mt = new Array(32).fill(0);
    let nt = 0;
    let ml = new Array(32).fill(0);
    let nl = 0;
    const rng2 = lcg(78);
    for (let i = 0; i < 200; i++) {
      const xt = [rng2(), rng2()]; // train ~ U[0,1]
      const xl = [rng2() + 1.5, rng2()]; // live shifted
      const r1 = updateMeanEmbedding(mt, nt, rffMap(xt, W, b));
      mt = r1.mean; nt = r1.n;
      const r2 = updateMeanEmbedding(ml, nl, rffMap(xl, W, b));
      ml = r2.mean; nl = r2.n;
    }
    const { stat, drift } = mmdWitness(mt, ml, 0.05);
    expect(stat).toBeGreaterThan(0.05);
    expect(drift).toBe(true);
  });
  it("no drift when streams match", () => {
    const m = [0.1, 0.2];
    const { drift } = mmdWitness(m, [...m], 0.05);
    expect(drift).toBe(false);
    expect(() => mmdWitness([1], [1, 2], 0.1)).toThrow();
    expect(() => rffMap([1, 2], [[[1]] as unknown as number[][]][0] as never, [0])).toThrow();
  });
});

/**
 * arXiv:2604.24366v2 — The Anatomy of a Decentralized Prediction Market: Microstructure Evidence from the Polymarket Order Book
 *
 * One-pass covariate-shift detection for the production feature pipeline: an online MMD witness built from
 * random Fourier features flags drift between training and live features and triggers a model refresh.
 *
 * Improvement: Port the CLOB-to-on-chain join pipeline to replicate the eight stylized facts on NFL/CFB Polymarket markets; build a longshot spread-premium curve by sport to downweight wide-spread market prices in GSE's signal fusion; adopt the wash-share lower-bound detector as a market-quality filter before trusting any venue's volume figures.
 *
 * ADDITIVE utility. Not wired into any live model path (wiring changes predictions and is a NEEDS HUMAN CALL).
 *
 * ACCEPTANCE GATE: Adopt the sports-only replication and the spread-premium signal-weighting if direction-agreement and stylized facts replicate within sampling noise.
 */

/** Random Fourier feature map (deterministic via the provided rng). */
export function rffMap(
  x: readonly number[],
  W: readonly (readonly number[])[],
  b: readonly number[],
): number[] {
  if (W.length !== b.length) throw new Error("rffMap: W/b mismatch");
  return W.map((w, i) => {
    if (w.length !== x.length) throw new Error("rffMap: dim mismatch");
    const z = w.reduce((s, wij, j) => s + wij * (x[j] ?? 0), 0) + (b[i] ?? 0);
    return Math.SQRT2 * Math.cos(z);
  });
}

/** Draw a random Fourier matrix (Gaussian) deterministically. */
export function drawRffParams(
  dim: number,
  nFeatures: number,
  rng: () => number,
  gamma = 1,
): { W: number[][]; b: number[] } {
  // Box-Muller from the uniform rng
  const gauss = (): number => {
    const u1 = Math.max(1e-12, rng());
    const u2 = rng();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  };
  const W = Array.from({ length: nFeatures }, () =>
    Array.from({ length: dim }, () => gauss() * Math.sqrt(2 * gamma)),
  );
  const b = Array.from({ length: nFeatures }, () => rng() * 2 * Math.PI);
  return { W, b };
}

/** Online mean embeddings for train and live streams. */
export function updateMeanEmbedding(
  mean: readonly number[],
  n: number,
  phi: readonly number[],
): { mean: number[]; n: number } {
  if (mean.length !== phi.length) throw new Error("updateMeanEmbedding: dim mismatch");
  const n2 = n + 1;
  return { mean: mean.map((m, i) => m + ((phi[i] ?? 0) - m) / n2), n: n2 };
}

/**
 * MMD witness statistic: squared distance between mean embeddings.
 * Drift fires when it exceeds the threshold.
 */
export function mmdWitness(
  meanTrain: readonly number[],
  meanLive: readonly number[],
  threshold: number,
): { stat: number; drift: boolean } {
  if (meanTrain.length !== meanLive.length) throw new Error("mmdWitness: dim mismatch");
  const stat = meanTrain.reduce((s, m, i) => s + ((meanLive[i] ?? 0) - m) ** 2, 0);
  return { stat, drift: stat > threshold };
}

